python3 - <<'EOF'
import os,re,collections
def mod2path(m):
    return m.replace('.','/')+'.lean'
allf=set()
for r,d,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): allf.add(os.path.join(r,f))
print('files under AlgebraicJacobian/:',len(allf))
seen=set()
stack=['AlgebraicJacobian.lean']
imp=re.compile(r'^import\s+(AlgebraicJacobian[\w.]*)')
while stack:
    p=stack.pop()
    if p in seen or not os.path.exists(p): continue
    seen.add(p)
    for line in open(p,encoding='utf8',errors='ignore'):
        m=imp.match(line.strip())
        if m:
            q=mod2path(m.group(1))
            if q not in seen: stack.append(q)
reach=seen&allf
print('reachable under AlgebraicJacobian/:',len(reach))
print('unreachable:',len(allf-reach))
un=sorted(allf-reach)
hw=[x for x in un if 'DivSchemeHighWindow' in x]
print('  of which DivSchemeHighWindow*:',len(hw))
for x in un:
    if 'Scratch' in x or 'Probe' in x: print('  SCRATCH/PROBE UNROOTED:',x)
EOF

